declare const brand: unique symbol;

type Brand<T, B extends string> = T & { readonly [brand]: B };

/** UTC timestamp in `Date.prototype.toISOString` form. Lexicographic order matches time. */
export type IsoTimestamp = Brand<string, "IsoTimestamp">;

export type OrgId = Brand<string, "OrgId">;
export type UserId = Brand<string, "UserId">;
export type SessionId = Brand<string, "SessionId">;

/** Normalizes a `Date` or a parseable timestamp to a comparable ISO string. */
export function toIsoTimestamp(value: Date | string): IsoTimestamp {
  const date = value instanceof Date ? value : new Date(value);
  if (Number.isNaN(date.getTime())) {
    throw new Error(`Cannot convert "${String(value)}" to an ISO timestamp`);
  }
  return date.toISOString() as IsoTimestamp;
}

import { randomBytes } from "node:crypto";

const CROCKFORD = "0123456789ABCDEFGHJKMNPQRSTVWXYZ";

/** 26-character id, the same width as `ANONYMOUS_ORG`. */
export function newId(): string {
  const bytes = randomBytes(26);
  let id = "";
  for (let i = 0; i < 26; i++) {
    id += CROCKFORD[bytes[i]! & 31];
  }
  return id;
}

/** Account addresses are compared without regard to letter case or surrounding space. */
export function normalizeEmail(email: string): string {
  return email.trim().toLowerCase();
}

import { randomBytes, scryptSync, timingSafeEqual } from "node:crypto";

const SCRYPT_N = 16384;
const SCRYPT_R = 8;
const SCRYPT_P = 1;
const KEY_LEN = 32;

/** Stores a salted scrypt hash. The same input verifies later; a different one does not. */
export function hashPassword(password: string): string {
  const salt = randomBytes(16).toString("hex");
  const hash = scryptSync(password, salt, KEY_LEN, {
    N: SCRYPT_N,
    r: SCRYPT_R,
    p: SCRYPT_P,
  }).toString("hex");
  return `scrypt$${SCRYPT_N}$${SCRYPT_R}$${SCRYPT_P}$${salt}$${hash}`;
}

export function verifyPassword(password: string, encoded: string): boolean {
  const parts = encoded.split("$");
  if (parts.length !== 6 || parts[0] !== "scrypt") return false;
  const [, nRaw, rRaw, pRaw, salt, hash] = parts;
  const n = Number(nRaw);
  const r = Number(rRaw);
  const p = Number(pRaw);
  if (!Number.isFinite(n) || !Number.isFinite(r) || !Number.isFinite(p) || !salt || !hash) {
    return false;
  }
  const actual = scryptSync(password, salt, KEY_LEN, { N: n, r, p });
  const expected = Buffer.from(hash, "hex");
  if (actual.length !== expected.length) return false;
  return timingSafeEqual(actual, expected);
}

import { createHash, randomBytes } from "node:crypto";

/** URL-safe secret that is emailed once and stored only as a hash. */
export function newSecretToken(): string {
  return randomBytes(32).toString("base64url");
}

export function hashToken(token: string): string {
  return createHash("sha256").update(token).digest("hex");
}

import { integer, sqliteTable, text } from "drizzle-orm/sqlite-core";

export const users = sqliteTable("users", {
  id: text("id").primaryKey(),
  email: text("email").notNull().unique(),
  passwordHash: text("password_hash").notNull(),
  name: text("name"),
  createdAt: text("created_at").notNull(),
});

export const organizations = sqliteTable("organizations", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  slug: text("slug").notNull().unique(),
  createdAt: text("created_at").notNull(),
});

export const memberships = sqliteTable("memberships", {
  id: text("id").primaryKey(),
  organizationId: text("organization_id").notNull(),
  userId: text("user_id").notNull(),
  role: text("role").notNull(),
  createdAt: text("created_at").notNull(),
});

export const sessions = sqliteTable("sessions", {
  id: text("id").primaryKey(),
  userId: text("user_id").notNull(),
  expiresAt: text("expires_at").notNull(),
  createdAt: text("created_at").notNull(),
  rememberMe: integer("remember_me", { mode: "boolean" }).notNull(),
});

export const passwordResetTokens = sqliteTable("password_reset_tokens", {
  id: text("id").primaryKey(),
  userId: text("user_id").notNull(),
  tokenHash: text("token_hash").notNull(),
  expiresAt: text("expires_at").notNull(),
  usedAt: text("used_at"),
  createdAt: text("created_at").notNull(),
});

/** Sign-in failures and reset requests are counted separately, per address. */
export const authAttempts = sqliteTable("auth_attempts", {
  id: text("id").primaryKey(),
  email: text("email").notNull(),
  kind: text("kind").notNull(),
  createdAt: text("created_at").notNull(),
});

export const schema = {
  users,
  organizations,
  memberships,
  sessions,
  passwordResetTokens,
  authAttempts,
};

import Database from "better-sqlite3";
import { drizzle } from "drizzle-orm/better-sqlite3";
import { schema } from "./schema";

const SCHEMA_SQL = `
CREATE TABLE IF NOT EXISTS users (
  id TEXT PRIMARY KEY NOT NULL,
  email TEXT NOT NULL UNIQUE,
  password_hash TEXT NOT NULL,
  name TEXT,
  created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS organizations (
  id TEXT PRIMARY KEY NOT NULL,
  name TEXT NOT NULL,
  slug TEXT NOT NULL UNIQUE,
  created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS memberships (
  id TEXT PRIMARY KEY NOT NULL,
  organization_id TEXT NOT NULL,
  user_id TEXT NOT NULL,
  role TEXT NOT NULL,
  created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS sessions (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  created_at TEXT NOT NULL,
  remember_me INTEGER NOT NULL DEFAULT 0
);
CREATE TABLE IF NOT EXISTS password_reset_tokens (
  id TEXT PRIMARY KEY NOT NULL,
  user_id TEXT NOT NULL,
  token_hash TEXT NOT NULL,
  expires_at TEXT NOT NULL,
  used_at TEXT,
  created_at TEXT NOT NULL
);
CREATE TABLE IF NOT EXISTS auth_attempts (
  id TEXT PRIMARY KEY NOT NULL,
  email TEXT NOT NULL,
  kind TEXT NOT NULL,
  created_at TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS auth_attempts_lookup ON auth_attempts (email, kind, created_at);
CREATE INDEX IF NOT EXISTS sessions_user ON sessions (user_id);
CREATE INDEX IF NOT EXISTS password_reset_tokens_hash ON password_reset_tokens (token_hash);
`;

type AppDatabase = ReturnType<typeof drizzle<typeof schema>>;

const connections = new Map<string, AppDatabase>();

function databaseFile(): string {
  return process.env.DATABASE_URL || ":memory:";
}

/** Opens (and caches) the application database, creating tables the first time. */
export function getDb(): AppDatabase {
  const filename = databaseFile();
  const cached = connections.get(filename);
  if (cached) return cached;
  const sqlite = new Database(filename);
  if (!filename.includes(":memory:")) {
    sqlite.pragma("journal_mode = WAL");
  }
  sqlite.exec(SCHEMA_SQL);
  const db = drizzle(sqlite, { schema });
  connections.set(filename, db);
  return db;
}

export {
  authAttempts,
  memberships,
  organizations,
  passwordResetTokens,
  schema,
  sessions,
  users,
} from "./schema";

