import { eq, lt } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, sessions } from "@/server/db";
import { toIsoTimestamp, type IsoTimestamp } from "@/types/common";

export type SessionRecord = {
  id: string;
  userId: string;
  expiresAt: IsoTimestamp;
  createdAt: IsoTimestamp;
  rememberMe: boolean;
};

function mapSession(row: typeof sessions.$inferSelect): SessionRecord {
  return {
    id: row.id,
    userId: row.userId,
    expiresAt: toIsoTimestamp(row.expiresAt),
    createdAt: toIsoTimestamp(row.createdAt),
    rememberMe: row.rememberMe,
  };
}

/**
 * Opens one session for one account. Each call inserts a new row, so a later
 * sign-in does not revive or replace any other device.
 */
export async function createSession(input: {
  userId: string;
  expiresAt: IsoTimestamp;
  createdAt?: IsoTimestamp;
  rememberMe?: boolean;
}): Promise<SessionRecord> {
  const createdAt = input.createdAt ?? toIsoTimestamp(new Date());
  const rows = getDb()
    .insert(sessions)
    .values({
      id: newId(),
      userId: input.userId,
      expiresAt: input.expiresAt,
      createdAt,
      rememberMe: input.rememberMe ?? false,
    })
    .returning()
    .all();
  const row = rows[0];
  if (!row) throw new Error("Failed to create session");
  return mapSession(row);
}

/**
 * Returns the session only while it is still inside its own expiry.
 * A missing row and a row whose `expiresAt` is already past are both refused.
 */
export async function findSession(
  sessionId: string,
  now: IsoTimestamp = toIsoTimestamp(new Date()),
): Promise<SessionRecord | null> {
  if (!sessionId) return null;
  const row = getDb().select().from(sessions).where(eq(sessions.id, sessionId)).get();
  if (!row) return null;
  if (row.expiresAt < now) return null;
  return mapSession(row);
}

/** Ends that session and only that one. An unknown id deletes nothing. */
export async function deleteSession(sessionId: string): Promise<void> {
  if (!sessionId) return;
  getDb().delete(sessions).where(eq(sessions.id, sessionId)).run();
}

/** Ends every session of one account. Other accounts are left signed in. */
export async function deleteSessionsForUser(userId: string): Promise<number> {
  if (!userId) return 0;
  const rows = getDb()
    .delete(sessions)
    .where(eq(sessions.userId, userId))
    .returning({ id: sessions.id })
    .all();
  return rows.length;
}

/** Housekeeping sweep; returns how many rows the scheduler removed. */
export async function purgeExpiredSessions(now: IsoTimestamp): Promise<number> {
  const rows = getDb()
    .delete(sessions)
    .where(lt(sessions.expiresAt, now))
    .returning({ id: sessions.id })
    .all();
  return rows.length;
}

/**
 * Password-reset tokens live here and nowhere else.
 *
 * A link is a row in `password_reset_tokens`. The repository that inserts the
 * entry owns it, and `AuthService` cannot implement a real reset flow without
 * somewhere to keep the single-use token.
 */
import { and, eq, gt, isNull } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, passwordResetTokens } from "@/server/db";
import { toIsoTimestamp, type IsoTimestamp } from "@/types/common";

export type ResetToken = {
  id: string;
  userId: string;
  tokenHash: string;
  expiresAt: IsoTimestamp;
  usedAt: IsoTimestamp | null;
};

function mapToken(row: typeof passwordResetTokens.$inferSelect): ResetToken {
  return {
    id: row.id,
    userId: row.userId,
    tokenHash: row.tokenHash,
    expiresAt: toIsoTimestamp(row.expiresAt),
    usedAt: row.usedAt ? toIsoTimestamp(row.usedAt) : null,
  };
}

export async function insertResetToken(input: {
  userId: string;
  tokenHash: string;
  expiresAt: IsoTimestamp;
}): Promise<ResetToken> {
  const rows = getDb()
    .insert(passwordResetTokens)
    .values({
      id: newId(),
      userId: input.userId,
      tokenHash: input.tokenHash,
      expiresAt: input.expiresAt,
      usedAt: null,
      createdAt: toIsoTimestamp(new Date()),
    })
    .returning()
    .all();
  const row = rows[0];
  if (!row) throw new Error("Failed to insert password reset token");
  return mapToken(row);
}

/**
 * Marks every still-unused link for this account as used. Links that belong
 * to any other account are left alone, including ones minted earlier.
 */
export async function retireUnusedResetTokens(userId: string, usedAt: IsoTimestamp): Promise<void> {
  if (!userId) return;
  getDb()
    .update(passwordResetTokens)
    .set({ usedAt })
    .where(and(eq(passwordResetTokens.userId, userId), isNull(passwordResetTokens.usedAt)))
    .run();
}

/** Returns the token only while it is unused and unexpired. */
export async function findLiveResetToken(tokenHash: string): Promise<ResetToken | null> {
  const row = getDb()
    .select()
    .from(passwordResetTokens)
    .where(
      and(
        eq(passwordResetTokens.tokenHash, tokenHash),
        isNull(passwordResetTokens.usedAt),
        gt(passwordResetTokens.expiresAt, new Date().toISOString()),
      ),
    )
    .get();
  if (!row) return null;
  return mapToken(row);
}

/**
 * Consumes a token at most once. A second call finds `usedAt` already set
 * and changes nothing, so a link that has already been used cannot succeed again.
 */
export async function consumeResetToken(id: string, usedAt: IsoTimestamp): Promise<boolean> {
  if (!id) return false;
  const rows = getDb()
    .update(passwordResetTokens)
    .set({ usedAt })
    .where(and(eq(passwordResetTokens.id, id), isNull(passwordResetTokens.usedAt)))
    .returning({ id: passwordResetTokens.id })
    .all();
  return rows.length === 1;
}

export {
  consumeResetToken,
  findLiveResetToken,
  insertResetToken,
  retireUnusedResetTokens,
  type ResetToken,
} from "./password-reset-repository";

import { eq, sql } from "drizzle-orm";
import { normalizeEmail } from "@/lib/email";
import { newId } from "@/lib/id";
import { getDb, memberships, organizations, users } from "@/server/db";
import { toIsoTimestamp, type IsoTimestamp } from "@/types/common";

export type UserRecord = {
  id: string;
  email: string;
  passwordHash: string;
  name: string | null;
  createdAt: IsoTimestamp;
};

function mapUser(row: typeof users.$inferSelect): UserRecord {
  return {
    id: row.id,
    email: row.email,
    passwordHash: row.passwordHash,
    name: row.name,
    createdAt: toIsoTimestamp(row.createdAt),
  };
}

/** Looks up an account by address, ignoring letter case. */
export async function findUserByEmail(email: string): Promise<UserRecord | null> {
  const normalized = normalizeEmail(email);
  if (!normalized) return null;
  const row = getDb()
    .select()
    .from(users)
    .where(sql`lower(${users.email}) = ${normalized}`)
    .get();
  return row ? mapUser(row) : null;
}

export async function findUserById(userId: string): Promise<UserRecord | null> {
  if (!userId) return null;
  const row = getDb().select().from(users).where(eq(users.id, userId)).get();
  return row ? mapUser(row) : null;
}

export async function insertUser(input: {
  email: string;
  passwordHash: string;
  name?: string | null;
}): Promise<UserRecord> {
  const rows = getDb()
    .insert(users)
    .values({
      id: newId(),
      email: normalizeEmail(input.email),
      passwordHash: input.passwordHash,
      name: input.name ?? null,
      createdAt: toIsoTimestamp(new Date()),
    })
    .returning()
    .all();
  const row = rows[0];
  if (!row) throw new Error("Failed to insert user");
  return mapUser(row);
}

export async function setPasswordHash(userId: string, passwordHash: string): Promise<void> {
  getDb().update(users).set({ passwordHash }).where(eq(users.id, userId)).run();
}

export async function insertOrganization(input: { name: string; slug: string }): Promise<{ id: string }> {
  const id = newId();
  getDb()
    .insert(organizations)
    .values({
      id,
      name: input.name,
      slug: input.slug,
      createdAt: toIsoTimestamp(new Date()),
    })
    .run();
  return { id };
}

export async function insertMembership(input: {
  organizationId: string;
  userId: string;
  role: string;
}): Promise<void> {
  getDb()
    .insert(memberships)
    .values({
      id: newId(),
      organizationId: input.organizationId,
      userId: input.userId,
      role: input.role,
      createdAt: toIsoTimestamp(new Date()),
    })
    .run();
}

import { and, eq, gt } from "drizzle-orm";
import { normalizeEmail } from "@/lib/email";
import { newId } from "@/lib/id";
import { authAttempts, getDb } from "@/server/db";
import type { IsoTimestamp } from "@/types/common";

export type AttemptKind = "sign_in" | "reset";

/**
 * Counts recent attempts for one address and one kind of limit.
 * Sign-in failures and reset requests never share a bucket, and one address
 * never adds to another address's count.
 */
export async function countRecentAttempts(
  email: string,
  kind: AttemptKind,
  since: IsoTimestamp,
): Promise<number> {
  const normalized = normalizeEmail(email);
  if (!normalized) return 0;
  const rows = getDb()
    .select({ id: authAttempts.id })
    .from(authAttempts)
    .where(
      and(
        eq(authAttempts.email, normalized),
        eq(authAttempts.kind, kind),
        gt(authAttempts.createdAt, since),
      ),
    )
    .all();
  return rows.length;
}

export async function recordAttempt(
  email: string,
  kind: AttemptKind,
  createdAt: IsoTimestamp,
): Promise<void> {
  const normalized = normalizeEmail(email);
  if (!normalized) return;
  getDb()
    .insert(authAttempts)
    .values({
      id: newId(),
      email: normalized,
      kind,
      createdAt,
    })
    .run();
}

import { normalizeEmail } from "@/lib/email";
import { newId } from "@/lib/id";
import { hashPassword, verifyPassword } from "@/lib/password";
import { hashToken, newSecretToken } from "@/lib/token";
import { countRecentAttempts, recordAttempt } from "@/server/repositories/auth-attempt-repository";
import {
  consumeResetToken,
  findLiveResetToken,
  insertResetToken,
  retireUnusedResetTokens,
} from "@/server/repositories/password-reset-repository";
import {
  createSession,
  deleteSession,
  deleteSessionsForUser,
  findSession,
  type SessionRecord,
} from "@/server/repositories/session-repository";
import {
  findUserByEmail,
  insertMembership,
  insertOrganization,
  insertUser,
  setPasswordHash,
} from "@/server/repositories/user-repository";
import { toIsoTimestamp, type IsoTimestamp, type OrgId } from "@/types/common";

/**
 * Nil workspace id. Registration creates a real workspace in the same step,
 * so this value is only a stand-in for callers that run before that exists.
 */
export const ANONYMOUS_ORG = "00000000000000000000000000" as OrgId;

/** A sign-in without "remember me" lasts 24 hours. */
export const SESSION_TTL_MS = 24 * 60 * 60 * 1000;

/** A sign-in with "remember me" lasts 30 days. */
export const REMEMBER_ME_TTL_MS = 30 * 24 * 60 * 60 * 1000;

/** How long a password-reset link stays usable. */
export const RESET_TTL_MS = 60 * 60 * 1000;

/**
 * Wrong sign-ins (and, separately, reset requests) accepted per address
 * inside the window. Past the limit the address is refused until the window
 * slides forward. Another address has its own count.
 */
export const ATTEMPT_LIMIT = 5;
export const ATTEMPT_WINDOW_MS = 15 * 60 * 1000;

export type AuthErrorCode =
  | "too_many_attempts"
  | "invalid_credentials"
  | "invalid_reset_token"
  | "email_taken";

export class AuthError extends Error {
  readonly code: AuthErrorCode;

  constructor(code: AuthErrorCode, message: string) {
    super(message);
    this.name = "AuthError";
    this.code = code;
  }
}

export type PasswordResetMail = {
  to: string;
  token: string;
  url: string;
};

export type AuthMailer = {
  sendPasswordReset(mail: PasswordResetMail): void | Promise<void>;
};

let mailer: AuthMailer = {
  sendPasswordReset() {},
};

/** Replaces the outbound reset mailer. Tests capture the link here. */
export function setAuthMailer(next: AuthMailer): void {
  mailer = next;
}

export type SignInResult = {
  sessionId: string;
  userId: string;
  expiresAt: IsoTimestamp;
  rememberMe: boolean;
};

export type SignInInput = {
  email: string;
  password: string;
  rememberMe?: boolean;
  remember?: boolean;
};

function windowStart(now: Date): IsoTimestamp {
  return toIsoTimestamp(new Date(now.getTime() - ATTEMPT_WINDOW_MS));
}

function wantsRememberMe(value: boolean | undefined): boolean {
  return value === true;
}

/**
 * Registration creates the user and their first workspace in one step — a
 * person should never land in the app without somewhere to stand.
 */
export async function register(input: {
  email: string;
  password: string;
  name?: string;
}): Promise<{ userId: string; orgId: string }> {
  const email = normalizeEmail(input.email);
  const existing = await findUserByEmail(email);
  if (existing) {
    throw new AuthError("email_taken", "An account with that email already exists");
  }
  const user = await insertUser({
    email,
    passwordHash: hashPassword(input.password),
    name: input.name ?? null,
  });
  const local = email.split("@")[0]?.replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "workspace";
  const org = await insertOrganization({
    name: input.name ? `${input.name}'s workspace` : "Workspace",
    slug: `${local}-${newId().slice(0, 8).toLowerCase()}`,
  });
  await insertMembership({ organizationId: org.id, userId: user.id, role: "owner" });
  return { userId: user.id, orgId: org.id };
}

export async function signUp(input: {
  email: string;
  password: string;
  name?: string;
}): Promise<{ userId: string; orgId: string }> {
  return register(input);
}

/**
 * Checks the password and opens one new session.
 * The session lasts 24 hours unless "remember me" is set, in which case it
 * lasts 30 days. A later sign-out of this session does not end any other.
 */
export async function signIn(input: SignInInput): Promise<SignInResult>;
export async function signIn(
  email: string,
  password: string,
  rememberMe?: boolean,
): Promise<SignInResult>;
export async function signIn(
  emailOrInput: string | SignInInput,
  password?: string,
  rememberMe?: boolean,
): Promise<SignInResult> {
  const input: SignInInput =
    typeof emailOrInput === "string"
      ? { email: emailOrInput, password: password ?? "", rememberMe }
      : emailOrInput;
  const email = normalizeEmail(input.email);
  const now = new Date();
  const recentFailures = await countRecentAttempts(email, "sign_in", windowStart(now));
  if (recentFailures >= ATTEMPT_LIMIT) {
    throw new AuthError("too_many_attempts", "too many attempts");
  }

  const user = await findUserByEmail(email);
  const passwordOk = user ? verifyPassword(input.password, user.passwordHash) : false;
  if (!user || !passwordOk) {
    await recordAttempt(email, "sign_in", toIsoTimestamp(now));
    throw new AuthError("invalid_credentials", "Invalid email or password");
  }

  const remember = wantsRememberMe(input.rememberMe) || wantsRememberMe(input.remember);
  const ttl = remember ? REMEMBER_ME_TTL_MS : SESSION_TTL_MS;
  const createdAt = toIsoTimestamp(now);
  const expiresAt = toIsoTimestamp(new Date(now.getTime() + ttl));
  const session = await createSession({
    userId: user.id,
