{"type":"SearchReplace","EditsApplied":{"old_string":"","new_string":"import { normalizeEmail } from "@/lib/email";
import { newId } from "@/lib/id";
import { hashPassword, verifyPassword } from "@/lib/password";
import { hashToken, newSecretToken } from "@/lib/token";
import { countRecentAttempts, recordAttempt } from "@/server/repositories/auth-attempt-repository";
import {
  consumeResetToken,
  findLiveResetToken,
  insertResetToken,
  retireUnusedResetTokens,
} from "@/server/repositories/password-reset-repository";
import {
  createSession,
  deleteSession,
  deleteSessionsForUser,
  findSession,
  type SessionRecord,
} from "@/server/repositories/session-repository";
import {
  findUserByEmail,
  insertMembership,
  insertOrganization,
  insertUser,
  setPasswordHash,
} from "@/server/repositories/user-repository";
import { toIsoTimestamp, type IsoTimestamp, type OrgId } from "@/types/common";

/**
 * Nil workspace id. Registration creates a real workspace in the same step,
 * so this value is only a stand-in for callers that run before that exists.
 */
export const ANONYMOUS_ORG = "00000000000000000000000000" as OrgId;

/** A sign-in without "remember me" lasts 24 hours. */
export const SESSION_TTL_MS = 24 * 60 * 60 * 1000;

/** A sign-in with "remember me" lasts 30 days. */
export const REMEMBER_ME_TTL_MS = 30 * 24 * 60 * 60 * 1000;

/** How long a password-reset link stays usable. */
export const RESET_TTL_MS = 60 * 60 * 1000;

/**
 * Wrong sign-ins (and, separately, reset requests) accepted per address
 * inside the window. Past the limit the address is refused until the window
 * slides forward. Another address has its own count.
 */
export const ATTEMPT_LIMIT = 5;
export const ATTEMPT_WINDOW_MS = 15 * 60 * 1000;

export type AuthErrorCode =
  | "too_many_attempts"
  | "invalid_credentials"
  | "invalid_reset_token"
  | "email_taken";

export class AuthError extends Error {
  readonly code: AuthErrorCode;

  constructor(code: AuthErrorCode, message: string) {
    super(message);
    this.name = "AuthError";
    this.code = code;
  }
}

export type PasswordResetMail = {
  to: string;
  token: string;
  url: string;
};

export type AuthMailer = {
  sendPasswordReset(mail: PasswordResetMail): void | Promise<void>;
};

let mailer: AuthMailer = {
  sendPasswordReset() {},
};

/** Replaces the outbound reset mailer. Tests capture the link here. */
export function setAuthMailer(next: AuthMailer): void {
  mailer = next;
}

export type SignInResult = {
  sessionId: string;
  userId: string;
  expiresAt: IsoTimestamp;
  rememberMe: boolean;
};

export type SignInInput = {
  email: string;
  password: string;
  rememberMe?: boolean;
  remember?: boolean;
};

function windowStart(now: Date): IsoTimestamp {
  return toIsoTimestamp(new Date(now.getTime() - ATTEMPT_WINDOW_MS));
}

function wantsRememberMe(value: boolean | undefined): boolean {
  return value === true;
}

/**
 * Registration creates the user and their first workspace in one step — a
 * person should never land in the app without somewhere to stand.
 */
export async function register(input: {
  email: string;
  password: string;
  name?: string;
}): Promise<{ userId: string; orgId: string }> {
  const email = normalizeEmail(input.email);
  const existing = await findUserByEmail(email);
  if (existing) {
    throw new AuthError("email_taken", "An account with that email already exists");
  }
  const user = await insertUser({
    email,
    passwordHash: hashPassword(input.password),
    name: input.name ?? null,
  });
  const local = email.split("@")[0]?.replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "workspace";
  const org = await insertOrganization({
    name: input.name ? `${input.name}'s workspace` : "Workspace",
    slug: `${local}-${newId().slice(0, 8).toLowerCase()}`,
  });
  await insertMembership({ organizationId: org.id, userId: user.id, role: "owner" });
  return { userId: user.id, orgId: org.id };
}

export async function signUp(input: {
  email: string;
  password: string;
  name?: string;
}): Promise<{ userId: string; orgId: string }> {
  return register(input);
}

/**
 * Checks the password and opens one new session.
 * The session lasts 24 hours unless "remember me" is set, in which case it
 * lasts 30 days. A later sign-out of this session does not end any other.
 */
export async function signIn(input: SignInInput): Promise<SignInResult>;
export async function signIn(
  email: string,
  password: string,
  rememberMe?: boolean,
): Promise<SignInResult>;
export async function signIn(
  emailOrInput: string | SignInInput,
  password?: string,
  rememberMe?: boolean,
): Promise<SignInResult> {
  const input: SignInInput =
    typeof emailOrInput === "string"
      ? { email: emailOrInput, password: password ?? "", rememberMe }
      : emailOrInput;
  const email = normalizeEmail(input.email);
  const now = new Date();
  const recentFailures = await countRecentAttempts(email, "sign_in", windowStart(now));
  if (recentFailures >= ATTEMPT_LIMIT) {
    throw new AuthError("too_many_attempts", "too many attempts");
  }

  const user = await findUserByEmail(email);
  const passwordOk = user ? verifyPassword(input.password, user.passwordHash) : false;
  if (!user || !passwordOk) {
    await recordAttempt(email, "sign_in", toIsoTimestamp(now));
    throw new AuthError("invalid_credentials", "Invalid email or password");
  }

  const remember = wantsRememberMe(input.rememberMe) || wantsRememberMe(input.remember);
  const ttl = remember ? REMEMBER_ME_TTL_MS : SESSION_TTL_MS;
  const createdAt = toIsoTimestamp(now);
  const expiresAt = toIsoTimestamp(new Date(now.getTime() + ttl));
  const session = await createSession({
    userId: user.id,
    expiresAt,
    createdAt,
    rememberMe: remember,
  });
  return {
    sessionId: session.id,
    userId: user.id,
    expiresAt: session.expiresAt,
    rememberMe: session.rememberMe,
  };
}

export async function login(input: SignInInput): Promise<SignInResult>;
export async function login(email: string, password: string, rememberMe?: boolean): Promise<SignInResult>;
export async function login(
  emailOrInput: string | SignInInput,
  password?: string,
  rememberMe?: boolean,
): Promise<SignInResult> {
  if (typeof emailOrInput === "string") return signIn(emailOrInput, password ?? "", rememberMe);
  return signIn(emailOrInput);
}

/**
 * Ends that session and only that one. The same account's other devices, and
 * every other account, stay signed in. An unknown or already-ended session
 * is a no-op so a repeated sign-out is harmless.
 */
export async function signOut(sessionId: string): Promise<void>;
export async function signOut(input: { sessionId?: string | null } | null | undefined): Promise<void>;
export async function signOut(
  sessionIdOrInput: string | { sessionId?: string | null } | null | undefined,
): Promise<void> {
  const sessionId =
    typeof sessionIdOrInput === "string" ? sessionIdOrInput : (sessionIdOrInput?.sessionId ?? "");
  await deleteSession(sessionId);
}

export async function logout(sessionId: string): Promise<void>;
export async function logout(input: { sessionId?: string | null } | null | undefined): Promise<void>;
export async function logout(
  sessionIdOrInput: string | { sessionId?: string | null } | null | undefined,
): Promise<void> {
  if (typeof sessionIdOrInput === "string") return signOut(sessionIdOrInput);
  return signOut(sessionIdOrInput);
}

/** Refuses a session that is missing or past its own expiry. */
export async function getSession(sessionId: string, now: Date = new Date()): Promise<SessionRecord | null> {
  return findSession(sessionId, toIsoTimestamp(now));
}

export async function readSession(sessionId: string, now?: Date): Promise<SessionRecord | null> {
  return getSession(sessionId, now);
}

export async function validateSession(sessionId: string, now?: Date): Promise<SessionRecord | null> {
  return getSession(sessionId, now);
}

/**
 * Sends a reset link when the address belongs to an account.
 * An unknown address still completes, with no link sent and no token stored.
 * A new link retires every earlier unused link of that account only.
 * Requests are limited per address, separately from sign-in failures, so a
 * throttled sign-in can still ask for a reset and one address cannot block another.
 */
export async function requestPasswordReset(email: string): Promise<string | null> {
  const normalized = normalizeEmail(email);
  const now = new Date();
  const recent = await countRecentAttempts(normalized, "reset", windowStart(now));
  if (recent >= ATTEMPT_LIMIT) {
    throw new AuthError("too_many_attempts", "too many attempts");
  }
  await recordAttempt(normalized, "reset", toIsoTimestamp(now));

  const user = await findUserByEmail(normalized);
  if (!user) return null;

  const nowIso = toIsoTimestamp(now);
  await retireUnusedResetTokens(user.id, nowIso);
  const token = newSecretToken();
  const expiresAt = toIsoTimestamp(new Date(now.getTime() + RESET_TTL_MS));
  await insertResetToken({
    userId: user.id,
    tokenHash: hashToken(token),
    expiresAt,
  });
  const mail: PasswordResetMail = {
    to: user.email,
    token,
    url: `/reset-password/${token}`,
  };
  await mailer.sendPasswordReset(mail);
  return token;
}

export async function forgotPassword(email: string): Promise<string | null> {
  return requestPasswordReset(email);
}

export async function sendPasswordReset(email: string): Promise<string | null> {
  return requestPasswordReset(email);
}

/**
 * Completes a live link exactly once. The link is usable for 60 minutes after
 * it was sent. Afterwards the new password signs in, the old one does not,
 * and every session of that account — and no other account — is ended.
 */
export async function resetPassword(token: string, newPassword: string): Promise<void>;
export async function resetPassword(input: {
  token: string;
  newPassword?: string;
  password?: string;
}): Promise<void>;
export async function resetPassword(
  tokenOrInput: string | { token: string; newPassword?: string; password?: string },
  newPassword?: string,
): Promise<void> {
  const token = typeof tokenOrInput === "string" ? tokenOrInput : tokenOrInput.token;
  const password =
    typeof tokenOrInput === "string"
      ? (newPassword ?? "")
      : (tokenOrInput.newPassword ?? tokenOrInput.password ?? "");
  const live = await findLiveResetToken(hashToken(token));
  if (!live) {
    throw new AuthError("invalid_reset_token", "This password reset link is no longer valid");
  }
  const passwordHash = hashPassword(password);
  const consumed = await consumeResetToken(live.id, toIsoTimestamp(new Date()));
  if (!consumed) {
    throw new AuthError("invalid_reset_token", "This password reset link is no longer valid");
  }
  await setPasswordHash(live.userId, passwordHash);
  await deleteSessionsForUser(live.userId);
}

export async function confirmPasswordReset(token: string, newPassword: string): Promise<void>;
export async function confirmPasswordReset(input: {
  token: string;
  newPassword?: string;
  password?: string;
}): Promise<void>;
export async function confirmPasswordReset(
  tokenOrInput: string | { token: string; newPassword?: string; password?: string },
  newPassword?: string,
): Promise<void> {
  if (typeof tokenOrInput === "string") return resetPassword(tokenOrInput, newPassword ?? "");
  return resetPassword(tokenOrInput);
}

export async function completePasswordReset(token: string, newPassword: string): Promise<void>;
export async function completePasswordReset(input: {
  token: string;
  newPassword?: string;
  password?: string;
}): Promise<void>;
export async function completePasswordReset(
  tokenOrInput: string | { token: string; newPassword?: string; password?: string },
  newPassword?: string,
): Promise<void> {
  if (typeof tokenOrInput === "string") return resetPassword(tokenOrInput, newPassword ?? "");
  return resetPassword(tokenOrInput);
}

export class AuthService {
  constructor(private readonly customMailer?: AuthMailer) {}

  register = register;
  signUp = signUp;

  signIn(input: SignInInput): Promise<SignInResult>;
  signIn(email: string, password: string, rememberMe?: boolean): Promise<SignInResult>;
  signIn(
    emailOrInput: string | SignInInput,
    password?: string,
    rememberMe?: boolean,
  ): Promise<SignInResult> {
    if (typeof emailOrInput === "string") return signIn(emailOrInput, password ?? "", rememberMe);
    return signIn(emailOrInput);
  }

  login(input: SignInInput): Promise<SignInResult>;
  login(email: string, password: string, rememberMe?: boolean): Promise<SignInResult>;
  login(
    emailOrInput: string | SignInInput,
    password?: string,
    rememberMe?: boolean,
  ): Promise<SignInResult> {
    if (typeof emailOrInput === "string") return this.signIn(emailOrInput, password ?? "", rememberMe);
    return this.signIn(emailOrInput);
  }

